const events=$input.all().map(i=>i.json).filter(e=>e.id);
const par_camera={};const timestamps=[];
for(const evt of events){
  const cam=evt.camera||'inconnue';
  if(!par_camera[cam])par_camera[cam]={nb:0,derniere:null};
  par_camera[cam].nb++;
  if(evt.start_time){
    timestamps.push(evt.start_time);
    if(!par_camera[cam].derniere||evt.start_time>par_camera[cam].derniere)par_camera[cam].derniere=evt.start_time;
  }
}
timestamps.sort();
const derniere_ts=timestamps.length?timestamps[timestamps.length-1]:null;
const derniere_str=derniere_ts?new Date(derniere_ts*1000).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'}):'--';
const heures=Array(24).fill(0);
for(const ts of timestamps)heures[new Date(ts*1000).getHours()]++;
return [{json:{nb_events:events.length,par_camera,derniere_ts,derniere_detection:derniere_str,timeline_labels:JSON.stringify([...Array(24).keys()].map(h=>h+'h')),timeline_data:JSON.stringify(heures)}}];

const stats       = $('Code — Stats Frigate').first().json;
let alertes_all; try { alertes_all = $('Sheets — Alertes').all().filter(i=>!i.json.error).map((i,idx)=>({...i.json,_row:idx+2})); } catch(e) { alertes_all = []; }
let statut_rows; try { statut_rows = $('Sheets — Statut').all().filter(i=>!i.json.error).map(i=>i.json); } catch(e) { statut_rows = []; }
const statut_actuel = statut_rows.length ? statut_rows[statut_rows.length-1] : {Statut:'OK',Note:''};
const alertes_actives = alertes_all.filter(a=>String(a.Acquittée||a['Acquittée']||'').toUpperCase()!=='TRUE');
const alertes_hist = [...alertes_all].reverse().slice(0,30);

const now_ts = Math.floor(Date.now()/1000);
const diff_min = stats.derniere_ts ? Math.floor((now_ts-stats.derniere_ts)/60) : null;
const il_y_a = diff_min===null ? 'Aucune détection' :
               diff_min<1 ? "à l'instant" :
               diff_min<60 ? `il y a ${diff_min} min` :
               `il y a ${Math.floor(diff_min/60)}h${diff_min%60?String(diff_min%60)+'min':''}`;
const absence_crit = diff_min!==null && diff_min>120;
const statut_val = statut_actuel.Statut||'OK';
const sr_color = statut_val==='SOS'?'#DC2626':statut_val==='Surveiller'?'#F59E0B':'#10B981';
const has_alerts = alertes_actives.length>0;
const now_str = new Date().toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'});
const date_str = new Date().toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'});

let cams_html='';
for(const[cam,d]of Object.entries(stats.par_camera||{})){
  const last=d.derniere?new Date(d.derniere*1000).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'}):'--';
  cams_html+=`<div class="cam-card"><div class="cam-label">📷 ${cam.toUpperCase()}</div>` +
    `<img class="cam-img" data-cam="${cam}" src="" alt="">` +
    `<div class="cam-meta">${d.nb} passage(s) · ${last}</div></div>`;
}
if(!cams_html) cams_html='<div class="empty">Aucune caméra active</div>';

let alerts_html='';
if(!has_alerts){
  alerts_html='<div class="no-alert">✓ Aucune alerte — tout va bien</div>';
}else{
  alertes_actives.forEach(a=>{
    const type=a.Type_Alerte||a.type_alerte||'Alerte';
    const cam=(a['Caméra']||a.Camera||a.camera||'?').toUpperCase();
    const date=a.Date||''; const heure=a.Heure||'';
    const msg=a.Message||a.message||'';
    const crit=(a.Niveau_Urgence||a.niveau_urgence||'').toUpperCase()==='CRITIQUE';
    alerts_html+=`<div class="alert-card ${crit?'crit':'warn'}">
      <div class="alert-head"><span>${crit?'🔴':'🟡'}</span><div class="alert-title">${type}</div><div class="alert-cam">${cam}</div></div>
      <div class="alert-when">📅 ${date} à ${heure}</div>
      ${msg?`<div class="alert-msg">${msg}</div>`:''}
      <div class="alert-btns">
        <button class="btn-acq" onclick="acquitter(${a._row})">✅ Acquitter</button>
        <button class="btn-note" onclick="openNote(${a._row})">📝 Note</button>
      </div>
      <div class="note-wrap" id="nw-${a._row}" style="display:none">
        <textarea id="nt-${a._row}" placeholder="Saisir une note..."></textarea>
        <button class="btn-save" onclick="saveNote(${a._row})">💾 Enregistrer</button>
      </div></div>`;
  });
}

let hist_html='';
if(!alertes_hist.length) hist_html='<div class="empty">Aucun historique</div>';
else alertes_hist.forEach(a=>{
  const done=String(a.Acquittée||a['Acquittée']||'').toUpperCase()==='TRUE';
  hist_html+=`<div class="hist-row${done?' done':''}">
    <div class="hist-ico">${done?'✅':'⏳'}</div>
    <div><div class="hist-type">${a.Type_Alerte||'—'}</div>
    <div class="hist-meta">${a.Date||''} ${a.Heure||''} · ${(a['Caméra']||a.Camera||'--').toUpperCase()}</div>
    ${a.Note_Soignant?`<div class="hist-note">📝 ${a.Note_Soignant}</div>`:''}</div></div>`;
});

const html=`<!DOCTYPE html>
<html lang="fr"><head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1">
<meta name="apple-mobile-web-app-capable" content="yes">
<title>SeniorAssist</title>
<style>
:root{--blue:#2563EB;--green:#10B981;--red:#DC2626;--amber:#F59E0B;--bg:#F0F4F8;--card:#fff;--border:#DDE3EC;--txt:#111827;--muted:#6B7280}
*{box-sizing:border-box;margin:0;padding:0;-webkit-tap-highlight-color:transparent}
body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;background:var(--bg);color:var(--txt)}
.hdr{background:var(--blue);color:#fff;padding:14px 20px;position:sticky;top:0;z-index:100;box-shadow:0 3px 10px rgba(37,99,235,.35)}
.hdr-row{display:flex;justify-content:space-between;align-items:center;margin-bottom:3px}
.hdr-name{font-size:20px;font-weight:800;display:flex;align-items:center;gap:8px}
.dot{width:9px;height:9px;background:#4ADE80;border-radius:50%;animation:p 2s infinite;flex-shrink:0}
@keyframes p{0%,100%{opacity:1}50%{opacity:.4}}
.edit-btn{background:rgba(255,255,255,.2);border:none;color:#fff;width:30px;height:30px;border-radius:50%;font-size:14px;cursor:pointer}
.hdr-sub{font-size:13px;opacity:.8}
.hdr-time{font-size:13px;font-weight:700;opacity:.9}
.banner{padding:14px 20px;font-weight:800;font-size:15px;text-align:center;color:#fff;background:${has_alerts?'var(--red)':'var(--green)'}}
.layout{max-width:1100px;margin:0 auto;padding:14px}
@media(min-width:768px){
  .layout{display:grid;grid-template-columns:380px 1fr;gap:16px;align-items:start}
}
.col-r{display:flex;flex-direction:column;gap:14px}
.card{background:var(--card);border-radius:18px;box-shadow:0 2px 8px rgba(0,0,0,.07);overflow:hidden;margin-bottom:14px}
@media(min-width:768px){.card{margin-bottom:0}}
.card-h{padding:16px 18px 0;font-size:11px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}
.card-b{padding:14px 18px 18px}
.pres-big{font-size:38px;font-weight:900;line-height:1.1;margin-bottom:4px;color:${absence_crit?'var(--red)':'var(--txt)'}}
.pres-sub{font-size:13px;color:var(--muted);margin-bottom:14px}
.s-badge{display:inline-flex;align-items:center;gap:6px;padding:6px 18px;border-radius:24px;font-weight:800;font-size:14px;color:#fff;background:${sr_color};margin-bottom:10px}
.s-note{font-size:13px;color:var(--muted);font-style:italic;margin-bottom:12px}
.s-btns{display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px}
.sbtn{padding:14px 6px;border:2px solid;border-radius:14px;font-size:13px;font-weight:800;cursor:pointer;transition:.15s}
.sbtn:active{transform:scale(.97)}
.s-ok{background:#F0FDF4;border-color:#86EFAC;color:#15803D}
.s-surv{background:#FFFBEB;border-color:#FCD34D;color:#92400E}
.s-sos{background:#FFF1F2;border-color:#FDA4AF;color:#9F1239}
.cams-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.cam-card{background:var(--bg);border-radius:14px;overflow:hidden;border:1px solid var(--border)}
.cam-label{padding:8px 12px;font-size:12px;font-weight:800;color:var(--blue);background:#EFF6FF}
.cam-img{width:100%;aspect-ratio:16/9;object-fit:cover;display:block;background:#E5E7EB;min-height:80px}
.cam-meta{padding:7px 12px;font-size:11px;color:var(--muted)}
.no-alert{text-align:center;padding:24px;color:var(--green);font-weight:700;font-size:16px}
.alert-card{border-radius:14px;padding:16px;margin-bottom:12px;border:1px solid;border-left:5px solid}
.alert-card:last-child{margin-bottom:0}
.crit{background:#FEF2F2;border-color:#FECACA;border-left-color:var(--red)}
.warn{background:#FFFBEB;border-color:#FDE68A;border-left-color:var(--amber)}
.alert-head{display:flex;align-items:center;gap:10px;margin-bottom:6px}
.alert-title{font-weight:800;font-size:16px;flex:1}
.alert-cam{background:rgba(0,0,0,.08);padding:3px 10px;border-radius:20px;font-size:12px;font-weight:700}
.alert-when{font-size:12px;color:var(--muted);margin-bottom:8px}
.alert-msg{font-size:14px;line-height:1.5;margin-bottom:12px;color:#374151}
.alert-btns{display:flex;gap:10px}
.btn-acq{flex:1;background:var(--green);color:#fff;border:none;padding:13px;border-radius:12px;font-size:14px;font-weight:800;cursor:pointer}
.btn-note{flex:1;background:#EFF6FF;color:var(--blue);border:1px solid #BFDBFE;padding:13px;border-radius:12px;font-size:14px;font-weight:700;cursor:pointer}
.note-wrap{margin-top:12px}
.note-wrap textarea{width:100%;padding:12px;border:1px solid var(--border);border-radius:12px;font-size:14px;height:80px;resize:vertical;font-family:inherit}
.btn-save{margin-top:8px;width:100%;background:var(--blue);color:#fff;border:none;padding:11px;border-radius:12px;font-size:14px;font-weight:700;cursor:pointer}
.chart-w{padding:4px 0}
.hist-toggle{width:100%;background:none;border:none;padding:16px 18px;display:flex;justify-content:space-between;font-size:14px;font-weight:700;cursor:pointer;color:var(--txt)}
.hist-inner{padding:0 18px 14px;display:none}
.hist-row{display:flex;gap:12px;padding:11px 0;border-bottom:1px solid var(--border)}
.hist-row:last-child{border:none}
.hist-row.done{opacity:.4}
.hist-ico{font-size:18px;flex-shrink:0;margin-top:1px}
.hist-type{font-size:14px;font-weight:700}
.hist-meta{font-size:12px;color:var(--muted)}
.hist-note{font-size:12px;color:var(--blue);font-style:italic;margin-top:2px}
.empty{text-align:center;color:var(--muted);font-size:14px;padding:20px}
.refresh{text-align:center;font-size:12px;color:var(--muted);padding:12px 0 4px}
.modal{position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:200;display:none;align-items:center;justify-content:center;padding:20px}
.modal.open{display:flex}
.mbox{background:#fff;border-radius:20px;padding:28px 24px;width:100%;max-width:380px;box-shadow:0 20px 60px rgba(0,0,0,.2)}
.mbox h3{font-size:18px;font-weight:800;margin-bottom:16px}
.mbox input{width:100%;padding:14px;border:1.5px solid var(--border);border-radius:12px;font-size:16px;margin-bottom:16px;font-family:inherit;outline:none}
.mbtns{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.m-ok{background:var(--blue);color:#fff;border:none;padding:14px;border-radius:12px;font-weight:800;font-size:15px;cursor:pointer}
.m-cancel{background:var(--bg);border:1px solid var(--border);padding:14px;border-radius:12px;font-weight:600;font-size:15px;cursor:pointer}
</style></head>
<body>
<div class="hdr">
  <div class="hdr-row">
    <div class="hdr-name"><span class="dot"></span><span id="rn">Résident</span><button class="edit-btn" onclick="editName()">✏️</button></div>
    <span class="hdr-time">${now_str}</span>
  </div>
  <div class="hdr-sub">${date_str}</div>
</div>
<div class="banner">${has_alerts?'⚠️ '+alertes_actives.length+' alerte(s) active(s)':'✓ Tout va bien — aucune alerte'}</div>

<div class="layout">
  <div class="col-l">
    <div class="card">
      <div class="card-h">Présence du résident</div>
      <div class="card-b">
        <div class="pres-big">${il_y_a}</div>
        <div class="pres-sub">Dernière détection : ${stats.derniere_detection} · ${stats.nb_events} passage(s) (2h)</div>
        <div class="s-badge">${statut_val==='SOS'?'🔴':statut_val==='Surveiller'?'🟡':'🟢'} ${statut_val}</div>
        ${statut_actuel.Note?`<div class="s-note">${statut_actuel.Note}</div>`:''}
        <div class="s-btns">
          <button class="sbtn s-ok" onclick="setStatut('OK')">🟢<br>OK</button>
          <button class="sbtn s-surv" onclick="promptStatut('Surveiller')">🟡<br>Surveiller</button>
          <button class="sbtn s-sos" onclick="promptStatut('SOS')">🔴<br>SOS !</button>
        </div>
      </div>
    </div>
    <div class="card">
      <div class="card-h">Caméras en direct</div>
      <div class="card-b" style="padding-top:12px">
        <div class="cams-grid">${cams_html}</div>
      </div>
    </div>
  </div>
  <div class="col-r">
    <div class="card">
      <div class="card-h">Alertes actives (${alertes_actives.length})</div>
      <div class="card-b">${alerts_html}</div>
    </div>
    <div class="card">
      <div class="card-h">Activité 24h</div>
      <div class="card-b"><div class="chart-w"><canvas id="chart" height="90"></canvas></div></div>
    </div>
    <div class="card">
      <button class="hist-toggle" onclick="toggleH(this)"><span>📋 Historique (${alertes_hist.length})</span><span id="harr">▼</span></button>
      <div class="hist-inner" id="hinner">${hist_html}</div>
    </div>
  </div>
</div>
<div class="refresh">🔄 Actualisation dans <span id="cd">60</span>s</div>

<div class="modal" id="mn"><div class="mbox"><h3>✏️ Nom du résident</h3>
  <input id="ni" type="text" placeholder="Ex: M. Jean Dupont" maxlength="50">
  <div class="mbtns"><button class="m-cancel" onclick="closeM('mn')">Annuler</button><button class="m-ok" onclick="saveName()">Enregistrer</button></div>
</div></div>
<div class="modal" id="ms"><div class="mbox"><h3 id="mst">Changer statut</h3>
  <input id="si" type="text" placeholder="Note (facultatif)" maxlength="100">
  <div class="mbtns"><button class="m-cancel" onclick="closeM('ms')">Annuler</button><button class="m-ok" id="msok" onclick="confirmS()">Confirmer</button></div>
</div></div>

<script src="https://cdn.jsdelivr.net/npm/chart.js@4/dist/chart.umd.min.js"><\/script>
<script>
const rn=document.getElementById('rn');
const sv=localStorage.getItem('sa_name');
if(sv)rn.textContent=sv;
function editName(){document.getElementById('ni').value=rn.textContent;document.getElementById('mn').classList.add('open');setTimeout(()=>document.getElementById('ni').focus(),100);}
function saveName(){const v=document.getElementById('ni').value.trim();if(v){rn.textContent=v;localStorage.setItem('sa_name',v);}closeM('mn');}
document.getElementById('ni').addEventListener('keydown',e=>{if(e.key==='Enter')saveName();});
function closeM(id){document.getElementById(id).classList.remove('open');}

document.querySelectorAll('img.cam-img[data-cam]').forEach(img=>{
  const cam=img.dataset.cam;
  img.src=location.origin+'/webhook/seniorassist-cam?cam='+encodeURIComponent(cam)+'&t='+Date.now();
  img.onerror=()=>{img.alt='📷 '+cam.toUpperCase()+' — indisponible';};
});

window.addEventListener('load',()=>{
  const ctx=document.getElementById('chart');
  if(!ctx)return;
  try{new Chart(ctx,{type:'bar',data:{labels:${stats.timeline_labels},datasets:[{data:${stats.timeline_data},backgroundColor:'#3B82F6',borderRadius:4,label:'Détections'}]},options:{responsive:true,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,ticks:{stepSize:1,font:{size:10}},grid:{color:'#F3F4F6'}},x:{ticks:{font:{size:9},maxRotation:0},grid:{display:false}}}}});}catch(e){console.error(e);}
});

function toggleH(btn){const b=document.getElementById('hinner'),a=document.getElementById('harr');const o=b.style.display==='block';b.style.display=o?'none':'block';a.textContent=o?'▼':'▲';}

const ACT=location.origin+'/webhook/seniorassist-action';
function acquitter(row){if(!confirm('Acquitter cette alerte ?'))return;fetch(ACT,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'acquitter',row})}).then(()=>setTimeout(()=>location.reload(),500));}
function openNote(row){const nw=document.getElementById('nw-'+row);nw.style.display=nw.style.display==='none'?'block':'none';if(nw.style.display==='block')document.getElementById('nt-'+row).focus();}
function saveNote(row){const note=document.getElementById('nt-'+row).value.trim();if(!note){alert('Saisir une note.');return;}fetch(ACT,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'note',row,note})}).then(()=>setTimeout(()=>location.reload(),500));}

let _ps='';
function setStatut(s,n=''){fetch(ACT,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'statut',statut:s,note:n})}).then(()=>setTimeout(()=>location.reload(),800));}
function promptStatut(s){_ps=s;document.getElementById('mst').textContent=s==='SOS'?'🔴 Déclencher SOS':'🟡 Passer en surveillance';document.getElementById('msok').textContent=s==='SOS'?'🔴 Confirmer SOS':'🟡 Confirmer';document.getElementById('si').value='';document.getElementById('ms').classList.add('open');setTimeout(()=>document.getElementById('si').focus(),100);}
function confirmS(){const n=document.getElementById('si').value.trim();closeM('ms');setStatut(_ps,n);}
document.getElementById('si').addEventListener('keydown',e=>{if(e.key==='Enter')confirmS();});

let cd=60;const cdEl=document.getElementById('cd');
setInterval(()=>{cd--;if(cdEl)cdEl.textContent=cd;if(cd<=0)location.reload();},1000);
<\/script></body></html>`;
return [{json:{html}}];
